#!/usr/bin/env node
// Writes the static country data of the Country field:
//
//     node scripts/generate-countries.mjs
//
// The list of codes below is the 249 officially assigned ISO 3166-1
// alpha-2 codes. The names come from Node's ICU, which carries CLDR data,
// through Intl.DisplayNames. Nothing is fetched: the output depends only
// on the Node build that runs this, and each generated file names the
// Node, ICU and CLDR versions it was made with.
//
// It writes:
//   packages/vector/src/Support/Countries.php          English names, for PHP
//   packages/vector-ui/app/utils/countries/<tag>.ts    one file per locale
//
// It fails, writing nothing, when the list is not 249 unique sorted-able
// codes, when a locale is not supported by this Node, or when any code has
// no name in a locale (the ICU data lacks it).
import { mkdirSync, writeFileSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const root = fileURLToPath(new URL('..', import.meta.url))
const PHP_FILE = path.join(root, 'packages/vector/src/Support/Countries.php')
const TS_DIR = path.join(root, 'packages/vector-ui/app/utils/countries')

export const LOCALES = ['ar', 'de', 'en', 'es', 'fr', 'he', 'it', 'ja', 'ko', 'nl', 'pl', 'pt', 'pt-BR', 'ru', 'tr', 'uk', 'zh-Hans']

// The ICU locale a file's names come from, when it is not the file's own tag.
// ICU reads a bare "pt" as Brazilian Portuguese, but the UI labels "pt" as
// Portugal, so its names come from European Portuguese.
const SOURCE_LOCALES = { pt: 'pt-PT' }

const CODES_TEXT = `
AD AE AF AG AI AL AM AO AQ AR AS AT AU AW AX AZ
BA BB BD BE BF BG BH BI BJ BL BM BN BO BQ BR BS BT BV BW BY BZ
CA CC CD CF CG CH CI CK CL CM CN CO CR CU CV CW CX CY CZ
DE DJ DK DM DO DZ
EC EE EG EH ER ES ET
FI FJ FK FM FO FR
GA GB GD GE GF GG GH GI GL GM GN GP GQ GR GS GT GU GW GY
HK HM HN HR HT HU
ID IE IL IM IN IO IQ IR IS IT
JE JM JO JP
KE KG KH KI KM KN KP KR KW KY KZ
LA LB LC LI LK LR LS LT LU LV LY
MA MC MD ME MF MG MH MK ML MM MN MO MP MQ MR MS MT MU MV MW MX MY MZ
NA NC NE NF NG NI NL NO NP NR NU NZ
OM
PA PE PF PG PH PK PL PM PN PR PS PT PW PY
QA
RE RO RS RU RW
SA SB SC SD SE SG SH SI SJ SK SL SM SN SO SR SS ST SV SX SY SZ
TC TD TF TG TH TJ TK TL TM TN TO TR TT TV TW TZ
UA UG UM US UY UZ
VA VC VE VG VI VN VU
WF WS
YE YT
ZA ZM ZW
`

export const CODES = CODES_TEXT.trim().split(/\s+/)

function fail(message) {
    console.error(`generate-countries: ${message}`)
    process.exit(1)
}

function validateCodes(codes) {
    if (codes.length !== 249 || new Set(codes).size !== 249) {
        fail(`the code list must hold exactly 249 unique codes, found ${codes.length} (${new Set(codes).size} unique)`)
    }
    for (const code of codes) {
        if (!/^[A-Z]{2}$/.test(code)) {
            fail(`"${code}" is not an upper-case alpha-2 code`)
        }
    }
}

function namesFor(locale, codes) {
    if (Intl.DisplayNames.supportedLocalesOf([locale]).length !== 1) {
        fail(`this Node does not support the locale "${locale}"`)
    }
    const display = new Intl.DisplayNames([locale], { type: 'region', fallback: 'none' })
    const names = {}
    for (const code of [...codes].sort()) {
        const name = display.of(code)
        if (name === undefined || name === '' || name === code) {
            fail(`no name for ${code} in "${locale}": the ICU data lacks it`)
        }
        names[code] = name
    }
    return names
}

const quote = (text) => `'${text.replaceAll('\\', '\\\\').replaceAll("'", "\\'")}'`

function banner() {
    const { node, icu, cldr } = process.versions
    return `generated by scripts/generate-countries.mjs from CLDR data (Node ${node}, ICU ${icu}, CLDR ${cldr}); do not edit by hand`
}

function phpSource(names) {
    const rows = Object.entries(names).map(([code, name]) => `        '${code}' => ${quote(name)},`)
    return `<?php

declare(strict_types=1);

// ${banner()}

namespace Kinetis\\Vector\\Support;

/**
 * The officially assigned ISO 3166-1 alpha-2 country codes with their
 * English names.
 */
final class Countries
{
    /** @var array<string, string> */
    public const NAMES = [
${rows.join('\n')}
    ];

    /**
     * @return list<string> every code, sorted
     */
    public static function codes(): array
    {
        return array_keys(self::NAMES);
    }

    /** The English name of a code, or null when it is not an assigned code. */
    public static function name(string $code): ?string
    {
        return self::NAMES[$code] ?? null;
    }
}
`
}

function tsSource(names) {
    const rows = Object.entries(names).map(([code, name]) => `    ${code}: ${quote(name)},`)
    return `// ${banner()}
export default {
${rows.join('\n')}
} as const satisfies Record<string, string>
`
}

validateCodes(CODES)

const outputs = new Map()
for (const locale of LOCALES) {
    const names = namesFor(SOURCE_LOCALES[locale] ?? locale, CODES)
    outputs.set(path.join(TS_DIR, `${locale}.ts`), tsSource(names))
    if (locale === 'en') {
        outputs.set(PHP_FILE, phpSource(names))
    }
}

mkdirSync(path.dirname(PHP_FILE), { recursive: true })
mkdirSync(TS_DIR, { recursive: true })
for (const [file, source] of outputs) {
    writeFileSync(file, source)
}
console.log(`generate-countries: wrote ${outputs.size} files for ${CODES.length} codes (Node ${process.versions.node}, ICU ${process.versions.icu}, CLDR ${process.versions.cldr})`)
